from measure import *
import base64,html

def run():
 screen=json.loads((OUT/'screen.json').read_text());measure=json.loads((OUT/'measurements.json').read_text());compact=json.loads((OUT/'compact.json').read_text());compound=json.loads((OUT/'union-profile.json').read_text());secondary=json.loads((OUT/'secondary.json').read_text());short=[]
 for row in measure['rows']:
  if row['asset']!='tech-core' or row['node'] not in [53,54,55,56]:continue
  trial=next(t for t in row['trials']if t['kind']=='convex-hull');g=load_nodes(Path(row['source']))[2][row['node']];h=g[row['triangle_indices']];p,t,_,_=topology(h);hu=ConvexHull(p);target=p[hu.simplices]
  edges=np.sort(np.concatenate([t[:,[0,1]],t[:,[1,2]],t[:,[2,0]]]),axis=1);_,counts=np.unique(edges,axis=0,return_counts=True)
  box=row['box'];c,f,half=map(np.asarray,[box['center_mm'],box['axes_columns'],box['half_extents_mm']]);f=f[:,np.argsort(half)[::-1]];prefix=f'core-{row["node"]}-exact-hull';render_pair(row,g,h,target,f,c,max(half)*1.2,prefix)
  rec={**row,**trial,'kind':'exact-vertex-convex-hull','hull_vertices':len(hu.vertices),'preview_files':[prefix+'-before.png',prefix+'-diagnostic-after.png'],'hull_vertex_coordinates_world_mm':p[hu.vertices].tolist(),'source_closed_edges':bool(np.all(counts==2)),'source_boundary_edges':int(sum(counts==1)),'source_nonmanifold_edges':int(sum(counts>2)),'source_surface_area_mm2':float(np.linalg.norm(np.cross(h[:,1]-h[:,0],h[:,2]-h[:,0]),axis=1).sum()/2),'hull_surface_area_mm2':float(hu.area),'status':'native-hull research shortlist; exact selected island retained as convex envelope; other owner islands and all other nodes retained; no installation or FPS claim'}
  rec.pop('trials',None);short.append(rec)
 # Whole collision context, all owners kept; selected islands remain under their original owners.
 doc,components,nodes=load_nodes(Path(short[0]['source']));selected={r['node']:r for r in short};rest=[];before=[];after=[]
 for ni,g in nodes.items():
  if ni in selected:
   ids=np.array(selected[ni]['triangle_indices']);h=g[ids];before.append(h);rest.append(np.delete(g,ids,axis=0));p=np.unique(h.reshape(-1,3),axis=0);after.append(p[ConvexHull(p).simplices])
  else:rest.append(g)
 rest=np.concatenate(rest);before=np.concatenate(before);after=np.concatenate(after);whole=np.concatenate([rest,before]);lo=whole.min((0,1));hi=whole.max((0,1));c=(hi+lo)/2;cam=vtk.vtkCamera();cam.SetFocalPoint(*c);cam.SetPosition(*(c+np.array([2,-3,2])*2000));cam.SetViewUp(0,0,1);cam.ParallelProjectionOn();cam.SetParallelScale(max(hi-lo)*.62);bounds=tuple(v for pair in zip(lo,hi)for v in pair)
 for stage,g in [('before',before),('diagnostic-after',after)]:old_render(rest,g,cam,bounds,f'core-all-context-{stage}.png')
 for r in compact:r['status']='marginal: 0.5mm approximation with only 128 combined placed preview triangles saved; overlaps exact hull alternatives; not prioritized'
 compound['status']='rejected as efficient native compound: 89 leaves, per-leaf preview triangle increase, up to 0.997mm error on 2mm sheet'
 rejections=[dict(asset=r['asset'],node=r['node'],island=r['island'],reason='Interior triangle loss / major opening fill or no useful box fidelity',trials=[t for t in r['trials'] if r['node'] not in [53,54,55,56] or t['kind']=='box']) for r in measure['rows']]
 result=dict(rejections=rejections,reference=str(REF),reference_sha256=sha(REF),baseline_visual_placed=355542,baseline_collision_placed=545599,scope='Core, Base and Outpost collision only',pins=screen['pins'],screen_counts=screen['counts'],native_hull_shortlist=short,compact_hull_alternatives=compact,compound_rejection=compound,secondary_screen=secondary,exclusions=['Core nodes 22 and 68 excluded from scan and savings','Dart, Rune outside scope; reviewed Dart260/493 and Rune22/23/272/426 not counted','Prior nine Base panel selectors not used by any shortlisted replacement','No extrapolated geometry or symmetry matching'],totals=dict(disjoint_source_triangles_per_asset=sum(r['source_triangles']for r in short),placed_source_triangle_mesh_triangles_replaced=sum(r['native_placed_triangle_mesh_triangles_replaced']for r in short),native_leaves_per_asset=sum(r['native_leaf_count']for r in short),native_placed_leaves=sum(r['native_placed_leaves']for r in short),exact_hull_placed_preview_savings=sum(r['hypothetical_placed_preview_savings']for r in short),compact_alternative_placed_preview_savings=sum(r['hypothetical_placed_preview_savings']for r in compact)),method=dict(selectors='Zero-based triangle indices in scan.load_nodes concatenated mesh primitive order, after source active-scene transforms; indices SHA256 is little-endian i64 bytes; world signature little-endian f64 triangle coordinates in millimetres. Exact islands use identical transformed coordinates only; no tolerance weld.',ownership='Every original mesh node is the rigid owner; selectors replace only an exact island under that owner. Keep all residual triangles and other nodes. World matrices use GLTF metres; NPZ positions use active-scene millimetres.',measurement='All vertices in both directions, 30000 deterministic uniform area samples each direction, all triangle centroids and edge midpoints for primary exact hulls. Maxima, not percentiles. Compact alternatives use 50000 area samples and all vertices. Finite samples are not a continuous distance proof.',native='Each native convex hull uses source world hull points transformed into its original owner frame during a future exporter. Native hull leaves have no imported triangle mesh; preview surface tessellation has triangles. Residual owner geometry remains a triangle mesh. Runtime backend support does not imply current field exporter support: only cylinder native import exists.',limitations=['No continuous Hausdorff bound, all-pose/contact/clearance validation or adoption.','Native removed triangle mesh counts are not FPS estimates, nor a claim leaves are cheaper than source BVH.','Hull and compact alternatives overlap and cannot be added.','Research NPZ/PNG only: no field GLB, installed/frozen/runtime/visual edits, builds, dependencies or commits.']))
 (OUT/'shortlist.json').write_text(json.dumps(result,indent=2)+'\n')
 # Self-contained report with embedded images, independent of repository paths.
 def img(name):return '<img alt="'+html.escape(name)+'" src="data:image/png;base64,'+base64.b64encode((OUT/name).read_bytes()).decode()+'">'
 def pair(prefix):return '<div class="pair"><figure>'+img(prefix+'-before.png')+'<figcaption>Source collision; selected island orange</figcaption></figure><figure>'+img(prefix+'-diagnostic-after.png')+'<figcaption>Diagnostic hull; all remaining source geometry retained</figcaption></figure></div>'
 totals=result['totals'];table=''.join(f'<tr><td>{r["node"]} / island 0</td><td>{r["source_triangles"]}</td><td>{r["hull_vertices"]}</td><td>{r["preview_triangles"]}</td><td>{r["sampled_bidirectional_max_mm"]:.6f}</td><td>{r["minimum_oriented_extent_mm"]:.3f}</td></tr>'for r in short)
 content=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Core / Base / Outpost box-hull research</title><style>body{{font:15px/1.5 system-ui;color:#202631;max-width:1100px;margin:24px auto;padding:0 16px}}h1{{font-size:25px}}h2{{font-size:20px;margin-top:30px}}table{{border-collapse:collapse;width:100%}}td,th{{padding:8px;border-bottom:1px solid #ccd1d7;text-align:left}}.pair{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}img{{width:100%}}figure{{margin:0}}figcaption{{font-size:12px;color:#566}}code{{overflow-wrap:anywhere}}@media(max-width:600px){{.pair{{grid-template-columns:1fr}}table{{font-size:11px}}}}</style></head><body><h1>New equipment hull opportunities — research only</h1>
 <p><b>Four disjoint Core arm islands can be represented by four native convex hulls.</b> They contain 802 source triangles per asset, or 1,604 triangle-mesh triangles across the two pinned placements. Exact convex envelopes match all tested source/target vertices, area samples, triangle centroids and edge midpoints within 0.000050 mm. These selected islands are closed edge-manifold meshes. All other islands of each owner remain intact.</p>
 <p><b>No large display-mesh saving:</b> the exact hull previews also have 802 triangles per asset. The native opportunity is changing representation, not reducing their tessellation. A 0.5 mm inscribed alternative saves only 128 placed display triangles; its worst measured error is 0.455 mm, around 11.4% of a 4 mm local thickness. Treat it as a marginal alternative, not an additional saving.</p>
 <table><tr><th>Core node / exact island</th><th>Source triangles</th><th>Hull vertices</th><th>Preview triangles</th><th>Worst sampled mm</th><th>Local minimum span mm</th></tr>{table}</table>
 <p>Component: <code>technology-core/arm-and-shared</code>, ancestry source product 5112571. Each source mesh node retains its own rigid owner, source world matrix, ancestry and residual collision triangles. Coordinates here are source active-scene millimetres; full selectors, SHA-256 signatures and matrices are in <code>shortlist.json</code>. No symmetry multiplier: each listed source occurrence was measured independently; manifest placements = 2.</p>
 <h2>Matched source and exact-hull diagnostics</h2><p>Orange selects only the exact connected island. Grey is unchanged collision geometry. This is collision research; visuals, Core face, Armor and Rune are untouched. A coincident screw/attachment surface in grey is retained, never silently deleted.</p>'''
 for r in short:content+=f'<h3>Core node {r["node"]}, source {r["source_triangles"]} → preview {r["preview_triangles"]}; native 1 hull leaf</h3>'+pair(f'core-{r["node"]}-exact-hull')
 content+='<h2>Whole Core collision context</h2>'+pair('core-all-context')
 content+='''<h2>Rejected / marginal alternatives</h2><p><b>Outpost nodes 26, 28 and 30:</b> 204 triangles each; convex hulls need only 24 / 16 / 20 preview triangles. Initial all-vertex and reverse samples were almost exact. However, full forward area and triangle-feature checks reach 7.35 mm, about 49% of the local 14.98 mm thickness. Each member has 176 triangles crossing its interior envelope. Retaining them leaves only 4 / 12 / 8 source-triangle savings per asset (at most 48 placed across the three). Reject the 1,104 placed preview saving from deleting them. Matched exterior views can look identical while this failure remains hidden.</p>'''+pair('outpost-26-convex-hull')
 content+=f'''<p><b>Core node 65 slotted sheet:</b> 712 triangles, 640 × 237 × 2 mm envelope; whole hull reverse error 19.48 mm and box 28.16 mm, so reject both. Exact-coordinate convex merging produced 139 leaves and 916 exterior / 1,516 per-leaf preview triangles. A second projected-profile experiment retains all 14 openings (13 vents plus the large rectangular port), using a topology-preserving 0.2 mm outline simplification: 89 convex leaves, 648 exterior / 1,040 per-leaf preview triangles. Exterior sampled error reaches 0.997 mm, about 50% of 2 mm thickness. The apparent 128 placed exterior saving becomes a 656-triangle placed increase when rendering every leaf. Reject as an efficient native compound; do not fill vents or the port to improve the count. These leaf interfaces are internal compound faces, so exterior and per-leaf preview counts are reported separately.</p>'''+pair('core-65-union-profile')
 content+='''<p><b>Other large enclosures:</b> bounded dense-island screen covers 51 Core, 12 Base and 18 Outpost islands (81 total); the smaller-island follow-up adds eight compact-hull screens. Base main housing/side members and Outpost column/lower/upper clusters fill major gaps when hulled; representative reverse sampled errors are Base housing 277 mm, moving sides 216–217 mm, Outpost column 118 mm and upper cluster 66–157 mm. These are explicit rejections, not savings. Core sheet node 61 has 146 mm hull / 264 mm box fills. Core nodes 6 and 31 likewise fail at 75.6 and 24.0 mm box errors. The initial area-percentile box scores hid these errors, which the final bidirectional maxima expose.</p>
 <h2>Source pins, reproducibility and limits</h2><p>The installed reference is the 355,542 placed visual / 545,599 placed collision baseline in <code>out/rmuc2027-installed-reference-review/review.json</code>. All installed pin paths, all reference visual/collision assets and the review JSON were hashed before and after. <code>validation.json</code> records checks and artifact hashes. No installed, frozen, runtime or shared script writes; no dependencies, builds or commits.</p>
 <p>Primary verification: every source and target vertex, 30,000 deterministic uniform area samples in each direction, and every triangle centroid/edge midpoint. Compact/compound experiments use 50,000 area samples in each direction and all vertices. Finite maxima do not prove a continuous distance bound or collision contact equivalence. No all-pose clearance/solver benchmark was performed. Native triangle replacement is not an FPS claim; a future exporter must preserve each rigid owner and motion ancestry. Native backend hulls/boxes exist, but field import currently supports cylinders only. These NPZ previews are not installed assets.</p>
 <p>Excluded from all new totals: reviewed Core68 and Core22 cylinder trial; Dart260/493; Rune22/23/272/426; previous nine Base panel trials. No arena-static or Rune replacement research is included.</p>
 <p>Reproduce with existing <code>ocpenv/bin/python -B</code>, scripts in <code>benchmarks/2026-10-23-box-hull-equipment-r2/</code>: research.py, measure.py, compact.py, profile.py, union_profile.py, secondary.py, finalize.py. They reuse existing scanner and exact-island helpers by import without modifying them. Union-profile exploration uses the already installed Shapely library.</p></body></html>'''
 (OUT/'report.html').write_text(content)
 # Validate shortlist exact selectors / owner signatures, nonoverlap and pins.
 checked=[]
 for r in short:
  g=load_nodes(Path(r['source']))[2][r['node']];ids=np.array(r['triangle_indices'],dtype='<i8');assert hashlib.sha256(ids.tobytes()).hexdigest()==r['triangle_indices_sha256'];assert signature(g[ids])==r['world_triangle_f64_sha256'];assert r['source_closed_edges'];checked.append([r['asset'],r['node'],r['island']])
 assert len(set(tuple(x)for x in checked))==4
 for p,s in screen['pins'].items():assert sha(Path(p))==s
 artifacts={p.name:sha(p)for p in OUT.iterdir()if p.is_file() and p.name!='validation.json' and p.suffix!='.log'}
 (OUT/'validation.json').write_text(json.dumps(dict(all_input_pins_unchanged=True,pin_count=len(screen['pins']),shortlist_selectors_and_world_signatures_verified=checked,closed_edge_manifold_shortlist=True,totals=result['totals'],artifact_sha256=artifacts,limitations='Finite sampled surface metrics; not continuous/contact/native-runtime certification.'),indent=2)+'\n')
 print(json.dumps(result['totals']),flush=True)
